-- 「오늘의 록」 곡 433곡 추가 — PostgreSQL / Supabase용
--
-- 실행: Supabase 대시보드 → SQL Editor → New query → 이 파일 내용 전체 붙여넣기 → Run
-- 기존 500곡·회원·좋아요 기록은 건드리지 않고 곡만 추가합니다.
-- 이미 있는 곡(같은 제목+가수)은 건너뛰므로 여러 번 실행해도 중복으로 들어가지 않습니다.
-- 후보 500곡 중 iTunes 확인에서 오매칭 21곡·검색결과없음 46곡을 뺀 433곡입니다.

BEGIN;

CREATE TEMP TABLE new_songs (
  ord INTEGER, title TEXT, artist TEXT, year SMALLINT, genre TEXT, energy SMALLINT,
  theme TEXT, tone TEXT, reason TEXT, lyrics_url TEXT, moods TEXT[], weathers TEXT[]
) ON COMMIT DROP;


-- 자동 번호를 지금 있는 마지막 id 뒤로 맞춘 뒤 추가합니다.
SELECT setval(pg_get_serial_sequence('songs', 'id'), (SELECT MAX(id) FROM songs));

SELECT title, artist, year, genre, energy, theme, tone, reason, lyrics_url FROM new_songs ORDER BY ord
ON CONFLICT (title, artist) DO NOTHING;

SELECT s.id, m FROM new_songs n JOIN songs s ON s.title = n.title AND s.artist = n.artist, unnest(n.moods) AS m
ON CONFLICT DO NOTHING;

SELECT s.id, w FROM new_songs n JOIN songs s ON s.title = n.title AND s.artist = n.artist, unnest(n.weathers) AS w
ON CONFLICT DO NOTHING;

COMMIT;

-- 확인용 (기존 500곡이 그대로라면 결과: 933곡)
SELECT
  (SELECT COUNT(*) FROM songs)         AS songs,
  (SELECT COUNT(*) FROM song_moods)    AS moods,
  (SELECT COUNT(*) FROM song_weathers) AS weathers;
